                for x, y in zip(a, b):
                    d = abs(x-y)
                    if (x < 1514 < y) or (y < 1514 < x):
                        d += 1000
                    total += d*d
                    if x == y:
                        anch += 1
                if Fraction(total, L)*POW[anch]**2 <= Fraction(en, ed)**2:
                    nb.append(j)
            adj[i] = nb
            core[i] = len(nb) >= dmin
    labels = {}
    clusters = {}
    for i in sorted(adj):
        if not core[i] or i in labels:
